		public UpdateInformationViewModel Load(UpdateInformation instance) {
			fixedDateRange = new ();
			if (instance.fixedDateRange != default) {
				fixedDateRange.Load(instance.fixedDateRange);
			}
			interoperabilityIdentifier = instance.interoperabilityIdentifier;
			updateNumber = instance.updateNumber;
			updateType = instance.updateType;
			scaleMinimum = instance.scaleMinimum;
			source = instance.source;
			information.Clear();
			if (instance.information is not null) {
				foreach(var e in instance.information)
					information.Add(new informationViewModel().Load(e));
			}
			return this;
		}

		public override string Serialize() {
			var instance = new UpdateInformation {
				fixedDateRange = this.fixedDateRange?.Model,
				interoperabilityIdentifier = this.interoperabilityIdentifier,
				updateNumber = this.updateNumber,
				updateType = this.updateType,
				scaleMinimum = this.scaleMinimum,
				source = this.source,
				information = this.information.Select(e => e.Model).ToList(),
			};
			return System.Text.Json.JsonSerializer.Serialize(instance);
		}

		[Browsable(false)]
		public UpdateInformation Model => new () {
			fixedDateRange = this._fixedDateRange?.Model,
			interoperabilityIdentifier = this._interoperabilityIdentifier,
			updateNumber = this._updateNumber,
			updateType = this._updateType,
			scaleMinimum = this._scaleMinimum,
			source = this._source,
			information = this.information.Select(e => e.Model).ToList(),
		};

		public override informationBindingDefinition[] informationBindingDefinitions => UpdateInformation._informationBindingDefinitions;
		public override informationBindingDefinition[] informationBindingDefinitionsByPrimitive(Primitives primitive) => [.. UpdateInformation._informationBindingDefinitions.Where(e => !e.primitives.Any() || e.primitives.Contains(primitive))];

		public override featureBindingDefinition[] featureBindingDefinitions => UpdateInformation._featureBindingDefinitions;

		public UpdateInformationViewModel ParseInformationBindings(informationBinding[] bindings) {
			this.LoadInformationBinding(bindings);
			return this;
		}

		public UpdateInformationViewModel ParseFeatureBindings(featureBinding[] bindings) {
			this.LoadFeatureBinding(bindings);
			return this;
		}

		public override string? ToString() => $"Update Information";

		public UpdateInformationViewModel() : base() {
			information.CollectionChanged += (object? sender, System.Collections.Specialized.NotifyCollectionChangedEventArgs e) => {
				OnPropertyChanged(nameof(information));
			};
			UpdateAggregations.CollectionChanged += (object? sender, System.Collections.Specialized.NotifyCollectionChangedEventArgs e) => {
				OnFeatureBindingCollectionChanged(nameof(UpdateAggregations));
			};
			UpdatedInformations.CollectionChanged += (object? sender, System.Collections.Specialized.NotifyCollectionChangedEventArgs e) => {
				OnFeatureBindingCollectionChanged(nameof(UpdatedInformations));
			};
		}
