		public LandRegionViewModel Load(LandRegion instance) {
			categoryOfLandRegion.Clear();
			if (instance.categoryOfLandRegion is not null) {
				foreach(var e in instance.categoryOfLandRegion)
					categoryOfLandRegion.Add(e);
			}
			featureName.Clear();
			if (instance.featureName is not null) {
				foreach(var e in instance.featureName)
					featureName.Add(new featureNameViewModel().Load(e));
			}
			interoperabilityIdentifier = instance.interoperabilityIdentifier;
			natureOfSurface.Clear();
			if (instance.natureOfSurface is not null) {
				foreach(var e in instance.natureOfSurface)
					natureOfSurface.Add(e);
			}
			waterLevelEffect = instance.waterLevelEffect;
			scaleMinimum = instance.scaleMinimum;
			information.Clear();
			if (instance.information is not null) {
				foreach(var e in instance.information)
					information.Add(new informationViewModel().Load(e));
			}
			return this;
		}

		public override string Serialize() {
			var instance = new LandRegion {
				categoryOfLandRegion = this.categoryOfLandRegion.ToList(),
				featureName = this.featureName.Select(e => e.Model).ToList(),
				interoperabilityIdentifier = this.interoperabilityIdentifier,
				natureOfSurface = this.natureOfSurface.ToList(),
				waterLevelEffect = this.waterLevelEffect,
				scaleMinimum = this.scaleMinimum,
				information = this.information.Select(e => e.Model).ToList(),
			};
			return System.Text.Json.JsonSerializer.Serialize(instance);
		}

		[Browsable(false)]
		public LandRegion Model => new () {
			categoryOfLandRegion = this.categoryOfLandRegion.ToList(),
			featureName = this.featureName.Select(e => e.Model).ToList(),
			interoperabilityIdentifier = this._interoperabilityIdentifier,
			natureOfSurface = this.natureOfSurface.ToList(),
			waterLevelEffect = this._waterLevelEffect,
			scaleMinimum = this._scaleMinimum,
			information = this.information.Select(e => e.Model).ToList(),
		};

		public override informationBindingDefinition[] informationBindingDefinitions => LandRegion._informationBindingDefinitions;
		public override informationBindingDefinition[] informationBindingDefinitionsByPrimitive(Primitives primitive) => [.. LandRegion._informationBindingDefinitions.Where(e => !e.primitives.Any() || e.primitives.Contains(primitive))];

		public override featureBindingDefinition[] featureBindingDefinitions => LandRegion._featureBindingDefinitions;

		public LandRegionViewModel ParseInformationBindings(informationBinding[] bindings) {
			this.LoadInformationBinding(bindings);
			return this;
		}

		public LandRegionViewModel ParseFeatureBindings(featureBinding[] bindings) {
			this.LoadFeatureBinding(bindings);
			return this;
		}

		public override string? ToString() => $"Land Region";

		public LandRegionViewModel() : base() {
			categoryOfLandRegion.CollectionChanged += (object? sender, System.Collections.Specialized.NotifyCollectionChangedEventArgs e) => {
				OnPropertyChanged(nameof(categoryOfLandRegion));
			};
			featureName.CollectionChanged += (object? sender, System.Collections.Specialized.NotifyCollectionChangedEventArgs e) => {
				OnPropertyChanged(nameof(featureName));
			};
			natureOfSurface.CollectionChanged += (object? sender, System.Collections.Specialized.NotifyCollectionChangedEventArgs e) => {
				OnPropertyChanged(nameof(natureOfSurface));
			};
			information.CollectionChanged += (object? sender, System.Collections.Specialized.NotifyCollectionChangedEventArgs e) => {
				OnPropertyChanged(nameof(information));
			};
			AdditionalInformations.CollectionChanged += (object? sender, System.Collections.Specialized.NotifyCollectionChangedEventArgs e) => {
				OnInformationBindingCollectionChanged(nameof(AdditionalInformations));
			};
			UpdatedInformations.CollectionChanged += (object? sender, System.Collections.Specialized.NotifyCollectionChangedEventArgs e) => {
				OnFeatureBindingCollectionChanged(nameof(UpdatedInformations));
			};
			TextAssociations.CollectionChanged += (object? sender, System.Collections.Specialized.NotifyCollectionChangedEventArgs e) => {
