		public SpanOpeningViewModel Load(SpanOpening instance) {
			fixedDateRange = new ();
			if (instance.fixedDateRange != default) {
				fixedDateRange.Load(instance.fixedDateRange);
			}
			horizontalClearanceFixed = new ();
			if (instance.horizontalClearanceFixed != default) {
				horizontalClearanceFixed.Load(instance.horizontalClearanceFixed);
			}
			interoperabilityIdentifier = instance.interoperabilityIdentifier;
			verticalClearanceClosed = new ();
			if (instance.verticalClearanceClosed != default) {
				verticalClearanceClosed.Load(instance.verticalClearanceClosed);
			}
			verticalClearanceOpen = new ();
			if (instance.verticalClearanceOpen != default) {
				verticalClearanceOpen.Load(instance.verticalClearanceOpen);
			}
			verticalDatum = instance.verticalDatum;
			scaleMinimum = instance.scaleMinimum;
			information.Clear();
			if (instance.information is not null) {
				foreach(var e in instance.information)
					information.Add(new informationViewModel().Load(e));
			}
			pictorialRepresentation = instance.pictorialRepresentation;
			return this;
		}

		public override string Serialize() {
			var instance = new SpanOpening {
				fixedDateRange = this.fixedDateRange?.Model,
				horizontalClearanceFixed = this.horizontalClearanceFixed?.Model,
				interoperabilityIdentifier = this.interoperabilityIdentifier,
				verticalClearanceClosed = this.verticalClearanceClosed?.Model,
				verticalClearanceOpen = this.verticalClearanceOpen?.Model,
				verticalDatum = this.verticalDatum,
				scaleMinimum = this.scaleMinimum,
				information = this.information.Select(e => e.Model).ToList(),
				pictorialRepresentation = this.pictorialRepresentation,
			};
			return System.Text.Json.JsonSerializer.Serialize(instance);
		}

		[Browsable(false)]
		public SpanOpening Model => new () {
			fixedDateRange = this._fixedDateRange?.Model,
			horizontalClearanceFixed = this._horizontalClearanceFixed?.Model,
			interoperabilityIdentifier = this._interoperabilityIdentifier,
			verticalClearanceClosed = this._verticalClearanceClosed?.Model,
			verticalClearanceOpen = this._verticalClearanceOpen?.Model,
			verticalDatum = this._verticalDatum,
			scaleMinimum = this._scaleMinimum,
			information = this.information.Select(e => e.Model).ToList(),
			pictorialRepresentation = this._pictorialRepresentation,
		};

		public override informationBindingDefinition[] informationBindingDefinitions => SpanOpening._informationBindingDefinitions;
		public override informationBindingDefinition[] informationBindingDefinitionsByPrimitive(Primitives primitive) => [.. SpanOpening._informationBindingDefinitions.Where(e => !e.primitives.Any() || e.primitives.Contains(primitive))];

		public override featureBindingDefinition[] featureBindingDefinitions => SpanOpening._featureBindingDefinitions;

		public SpanOpeningViewModel ParseInformationBindings(informationBinding[] bindings) {
			this.LoadInformationBinding(bindings);
			return this;
		}

		public SpanOpeningViewModel ParseFeatureBindings(featureBinding[] bindings) {
			this.LoadFeatureBinding(bindings);
			return this;
		}

		public override string? ToString() => $"Span Opening";

		public SpanOpeningViewModel() : base() {
			information.CollectionChanged += (object? sender, System.Collections.Specialized.NotifyCollectionChangedEventArgs e) => {
				OnPropertyChanged(nameof(information));
			};
			AdditionalInformations.CollectionChanged += (object? sender, System.Collections.Specialized.NotifyCollectionChangedEventArgs e) => {
				OnInformationBindingCollectionChanged(nameof(AdditionalInformations));
			};
			BridgeAggregations.CollectionChanged += (object? sender, System.Collections.Specialized.NotifyCollectionChangedEventArgs e) => {
				OnFeatureBindingCollectionChanged(nameof(BridgeAggregations));
			};
			StructureEquipments.CollectionChanged += (object? sender, System.Collections.Specialized.NotifyCollectionChangedEventArgs e) => {
				OnFeatureBindingCollectionChanged(nameof(StructureEquipments));
			};
			AidsToNavigationAssociations.CollectionChanged += (object? sender, System.Collections.Specialized.NotifyCollectionChangedEventArgs e) => {
				OnFeatureBindingCollectionChanged(nameof(AidsToNavigationAssociations));
			};
			TextAssociations.CollectionChanged += (object? sender, System.Collections.Specialized.NotifyCollectionChangedEventArgs e) => {
				OnFeatureBindingCollectionChanged(nameof(TextAssociations));
			};
			UpdatedInformations.CollectionChanged += (object? sender, System.Collections.Specialized.NotifyCollectionChangedEventArgs e) => {
				OnFeatureBindingCollectionChanged(nameof(UpdatedInformations));
			};
		}
