		public FortifiedStructureViewModel Load(FortifiedStructure instance) {
			categoryOfFortifiedStructure = instance.categoryOfFortifiedStructure;
			condition = instance.condition;
			featureName.Clear();
			if (instance.featureName is not null) {
				foreach(var e in instance.featureName)
					featureName.Add(new featureNameViewModel().Load(e));
			}
			height = instance.height;
			interoperabilityIdentifier = instance.interoperabilityIdentifier;
			natureOfConstruction.Clear();
			if (instance.natureOfConstruction is not null) {
				foreach(var e in instance.natureOfConstruction)
					natureOfConstruction.Add(e);
			}
			radarConspicuous = instance.radarConspicuous;
			reportedDate = instance.reportedDate;
			status.Clear();
			if (instance.status is not null) {
				foreach(var e in instance.status)
					status.Add(e);
			}
			verticalLength = instance.verticalLength;
			visualProminence = instance.visualProminence;
			scaleMinimum = instance.scaleMinimum;
			information.Clear();
			if (instance.information is not null) {
				foreach(var e in instance.information)
					information.Add(new informationViewModel().Load(e));
			}
			pictorialRepresentation = instance.pictorialRepresentation;
			inTheWater = instance.inTheWater;
			return this;
		}

		public override string Serialize() {
			var instance = new FortifiedStructure {
				categoryOfFortifiedStructure = this.categoryOfFortifiedStructure,
				condition = this.condition,
				featureName = this.featureName.Select(e => e.Model).ToList(),
				height = this.height,
				interoperabilityIdentifier = this.interoperabilityIdentifier,
				natureOfConstruction = this.natureOfConstruction.ToList(),
				radarConspicuous = this.radarConspicuous,
				reportedDate = this.reportedDate,
				status = this.status.ToList(),
				verticalLength = this.verticalLength,
				visualProminence = this.visualProminence,
				scaleMinimum = this.scaleMinimum,
				information = this.information.Select(e => e.Model).ToList(),
				pictorialRepresentation = this.pictorialRepresentation,
				inTheWater = this.inTheWater,
			};
			return System.Text.Json.JsonSerializer.Serialize(instance);
		}

		[Browsable(false)]
		public FortifiedStructure Model => new () {
			categoryOfFortifiedStructure = this._categoryOfFortifiedStructure,
			condition = this._condition,
			featureName = this.featureName.Select(e => e.Model).ToList(),
			height = this._height,
			interoperabilityIdentifier = this._interoperabilityIdentifier,
			natureOfConstruction = this.natureOfConstruction.ToList(),
			radarConspicuous = this._radarConspicuous,
			reportedDate = this._reportedDate,
			status = this.status.ToList(),
			verticalLength = this._verticalLength,
			visualProminence = this._visualProminence,
			scaleMinimum = this._scaleMinimum,
			information = this.information.Select(e => e.Model).ToList(),
			pictorialRepresentation = this._pictorialRepresentation,
			inTheWater = this._inTheWater,
		};

		public override informationBindingDefinition[] informationBindingDefinitions => FortifiedStructure._informationBindingDefinitions;
		public override informationBindingDefinition[] informationBindingDefinitionsByPrimitive(Primitives primitive) => [.. FortifiedStructure._informationBindingDefinitions.Where(e => !e.primitives.Any() || e.primitives.Contains(primitive))];

		public override featureBindingDefinition[] featureBindingDefinitions => FortifiedStructure._featureBindingDefinitions;

		public FortifiedStructureViewModel ParseInformationBindings(informationBinding[] bindings) {
			this.LoadInformationBinding(bindings);
			return this;
		}

		public FortifiedStructureViewModel ParseFeatureBindings(featureBinding[] bindings) {
			this.LoadFeatureBinding(bindings);
			return this;
		}

		public override string? ToString() => $"Fortified Structure";

		public FortifiedStructureViewModel() : base() {
			featureName.CollectionChanged += (object? sender, System.Collections.Specialized.NotifyCollectionChangedEventArgs e) => {
				OnPropertyChanged(nameof(featureName));
			};
			natureOfConstruction.CollectionChanged += (object? sender, System.Collections.Specialized.NotifyCollectionChangedEventArgs e) => {
				OnPropertyChanged(nameof(natureOfConstruction));
			};
			status.CollectionChanged += (object? sender, System.Collections.Specialized.NotifyCollectionChangedEventArgs e) => {
				OnPropertyChanged(nameof(status));
			};
			information.CollectionChanged += (object? sender, System.Collections.Specialized.NotifyCollectionChangedEventArgs e) => {
				OnPropertyChanged(nameof(information));
			};
			AdditionalInformations.CollectionChanged += (object? sender, System.Collections.Specialized.NotifyCollectionChangedEventArgs e) => {
				OnInformationBindingCollectionChanged(nameof(AdditionalInformations));
			};
			StructureEquipments.CollectionChanged += (object? sender, System.Collections.Specialized.NotifyCollectionChangedEventArgs e) => {
				OnFeatureBindingCollectionChanged(nameof(StructureEquipments));
			};
			AidsToNavigationAssociations.CollectionChanged += (object? sender, System.Collections.Specialized.NotifyCollectionChangedEventArgs e) => {
				OnFeatureBindingCollectionChanged(nameof(AidsToNavigationAssociations));
			};
			RangeSystemAggregations.CollectionChanged += (object? sender, System.Collections.Specialized.NotifyCollectionChangedEventArgs e) => {
				OnFeatureBindingCollectionChanged(nameof(RangeSystemAggregations));
			};
			UpdatedInformations.CollectionChanged += (object? sender, System.Collections.Specialized.NotifyCollectionChangedEventArgs e) => {
				OnFeatureBindingCollectionChanged(nameof(UpdatedInformations));
			};
			TextAssociations.CollectionChanged += (object? sender, System.Collections.Specialized.NotifyCollectionChangedEventArgs e) => {
				OnFeatureBindingCollectionChanged(nameof(TextAssociations));
			};
		}
